<script setup>
import {previewMode} from '../preview/mode'

import {ref,computed,watch} from 'vue'
import Icon from '../Icon.vue'
import {isDemo} from '../service'
import {createProfile} from '../commerce/community'
import {safeLink} from '../rules'
const emit=defineEmits(['back','dashboard'])
const username=ref(''),bio=ref(''),grades=ref(''),curriculum=ref(''),socials=ref({facebook:'',instagram:'',twitter:'',youtube:''}),mobileCode=ref(''),mobileSent=ref(0),mobileAttempts=ref(0),profileResult=ref(null)
const challenge=ref('')
async function registrationCall(method,data){if(previewMode)throw Error('This action requires the connected server. No data was sent.');const response=await fetch('/api/method/institute_lms.registration.'+method,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':document.querySelector('meta[name=csrf-token]')?.content||window.csrf_token||''},body:JSON.stringify(data)});const body=await response.json();if(!response.ok||body.exc)throw Error('Registration could not continue. Check the entered details or contact the site administrator.');return body.message}
const kind=ref('Student'),step=ref('details'),mode=ref('signup'),email=ref(''),code=ref(''),error=ref(''),busy=ref(false),sentAt=ref(0),attempts=ref(0)
const fullName=ref(''),organization=ref(''),orgType=ref('Academy'),country=ref('Sri Lanka'),timezone=ref('Asia/Colombo'),language=ref('English'),subject=ref(''),invite=ref(''),businessDomain=ref(''),job=ref(''),phone=ref(''),backupName=ref(''),backupEmail=ref(''),students=ref(50),accepted=ref(false)
const isOwner=computed(()=>kind.value==='Super Admin'),isInstitute=computed(()=>kind.value==='Institute')
watch([kind,mode],()=>{step.value='details';code.value='';error.value='';accepted.value=false})
async function submit(){error.value='';busy.value=true;try{if(!isDemo){if(mode.value==='login'){location.assign('/login?redirect-to=/campus');return}const result=await registrationCall('request_code',{data:{kind:kind.value,email:email.value,full_name:fullName.value,organization:organization.value,organization_type:orgType.value,country:country.value,timezone:timezone.value,language:language.value,subject:subject.value,invite:invite.value,website:businessDomain.value,job:job.value,phone:phone.value,backup_name:backupName.value,backup_email:backupEmail.value}});challenge.value=result.challenge}else{if(isOwner.value&&email.value.trim().toLowerCase()!=='danusgalagoda@gmail.com')throw Error('This address is not eligible for owner access.');if(isInstitute.value&&mode.value==='signup'&&backupEmail.value.trim().toLowerCase()===email.value.trim().toLowerCase())throw Error('Use a different recovery contact email.')}sentAt.value=Date.now();attempts.value=0;step.value='verify'}catch(e){error.value=e.message}finally{busy.value=false}}
async function verify(){error.value='';busy.value=true;try{if(!isDemo){await registrationCall('verify_code',{challenge:challenge.value,code:code.value})}else{if(Date.now()-sentAt.value>=600000||attempts.value>=5)throw Error('Code expired. Return and request another code.');attempts.value++;if(code.value!=='123456')throw Error('That code did not match. Try the preview code shown below.')}step.value=isDemo&&!isOwner.value?'mobile':'complete'}catch(e){error.value=e.message}finally{busy.value=false}}


function google(){error.value='';if(!isDemo){location.assign('/login?redirect-to='+encodeURIComponent('/campus#signup'));return}if(isOwner.value){error.value='Owner access still requires the allowlisted email and verification code.';return}if(!email.value.includes('@')){error.value='Enter a fictional email above to try Google sign-in in this preview.';return}step.value='mobile';fullName.value=fullName.value||'Preview learner'}
function sendMobile(){error.value='';if(!/^\+[1-9][0-9]{7,14}$/.test(phone.value)){error.value='Use an international number beginning with + and a country code.';return}mobileSent.value=Date.now();mobileAttempts.value=0}
function verifyMobile(){error.value='';if(!mobileSent.value||Date.now()-mobileSent.value>=600000||mobileAttempts.value>=5){error.value='Request a fresh mobile code.';return}mobileAttempts.value++;if(mobileCode.value!=='123456'){error.value='Code did not match the preview code.';return}step.value='profile'}
function finishProfile(){error.value='';try{for(const url of Object.values(socials.value))if(url&&!safeLink(url))throw Error('Use valid HTTPS social profile links.');profileResult.value=createProfile({user:email.value.trim().toLowerCase(),username:username.value,display_name:isInstitute.value?organization.value:fullName.value,kind:isInstitute.value?'Institute':kind.value==='Individual Teacher'?'Teacher':'Student',country:country.value,bio:bio.value,grades:grades.value,curriculum:curriculum.value,languages:language.value,socials:socials.value,is_school:isInstitute.value&&orgType.value==='School'});step.value='complete'}catch(e){error.value=e.message}}

function enter(){const role=isOwner.value?'PlatformAdmin':isInstitute.value?'Admin':kind.value==='Individual Teacher'?'Teacher':'Student';emit('dashboard',role)}
</script>
<template><section class="signup-shell"><header><a href="#dashboard" @click.prevent="$emit('back')" class="signup-brand">sisu<span>.</span></a><button class="button subtle" @click="$emit('back')">Back to welcome</button></header><div class="signup-layout"><aside class="signup-story"><span class="eyebrow">A PLACE TO BEGIN AGAIN</span><h1>{{isOwner?'Your platform.\nA thoughtful beginning.':isInstitute?'Give your community\na place to grow.':kind==='Individual Teacher'?'Your teaching.\nA world of possibility.':'A small step today.\nA brighter tomorrow.'}}</h1><p>One learning home, built around you. Calm spaces, meaningful connections, and room for every little milestone.</p><div class="signup-art"><Icon name="Sprout" :size="100"/><span>✧</span><Icon name="BookOpen" :size="70"/></div><small>Web-first · International · Made for people</small></aside><main class="signup-form"><div class="signup-role-tabs" aria-label="Choose account type"><button v-for="r in ['Institute','Individual Teacher','Student']" :aria-pressed="kind===r" @click="kind=r">{{r}}</button></div><button class="text-button owner-entry" @click="kind='Super Admin'">Platform owner access</button><div class="inline"><button class="text-button" @click="mode='signup'">Create account</button><button class="text-button" @click="mode='login'">Sign in</button></div><h2>{{isOwner?'Super Admin':kind}} {{mode==='signup'?'sign up':'sign in'}}</h2><span class="badge violet">{{isDemo?'Interactive preview · no email sent':'Email verification · approval required'}}</span>
<form v-if="step==='details'" @submit.prevent="submit"><label v-if="mode==='signup'&&!isOwner">{{isInstitute?'Authorized person’s full name':'Full name'}}<input v-model="fullName" autocomplete="name" required maxlength="120"></label><label>{{isInstitute?'Business email':'Email address'}}<input v-model="email" type="email" required autocomplete="email" maxlength="254"></label><p v-if="isOwner" class="field-help">Owner access requires a server-configured email allowlist and a fresh verification code. Other registrations cannot select this privilege.</p><template v-if="mode==='signup'&&!isOwner"><template v-if="isInstitute"><label>Institute name<input v-model="organization" required maxlength="120"></label><div class="form-row"><label>Organization type<select v-model="orgType"><option>Academy</option><option>School</option><option>College</option><option>University</option><option>Training institute</option><option>Other</option></select></label><label>Your job title<input v-model="job" required maxlength="80"></label></div><label>Website (optional)<input v-model="businessDomain" type="url" placeholder="https://"></label><label>Authorized person’s phone<input v-model="phone" type="tel" required maxlength="25"></label><div class="form-row"><label>Recovery contact name<input v-model="backupName" required maxlength="120"></label><label>Recovery contact email<input v-model="backupEmail" type="email" required></label></div><p class="field-help">Business verification, recovery-contact verification and two-factor authentication are required before a real institute is activated.</p></template><label v-if="kind==='Individual Teacher'">Your subject or expertise<input v-model="subject" required maxlength="120" placeholder="Mathematics, design, languages…"></label><label v-if="kind==='Student'">Institute or teacher invitation code (optional)<input v-model="invite" maxlength="40" placeholder="Enter an invitation code"></label><div class="form-row"><label>Country<input v-model="country" required maxlength="80"></label><label>Time zone<input v-model="timezone" required placeholder="Asia/Colombo"></label></div><label>Preferred language<select v-model="language"><option>English</option><option>Sinhala</option><option>Tamil</option><option>Arabic</option><option>French</option><option>Spanish</option></select></label><template v-if="kind!=='Student'"><label>Expected active students<input v-model.number="students" min="1" max="1000000" type="number" required></label><p class="field-help">Your administrator assigns your account pricing. Your amount is shown at checkout before any payment.</p></template><p v-else class="field-help">Students do not pay the provider’s platform subscription. Your class fees and optional personal add-ons are separate.</p></template><label class="checkbox-label"><input v-model="accepted" type="checkbox" required>{{isDemo?'I understand this is a preview, not a live account or subscription.':'I request account review and consent to a verification email.'}}</label><button class="google-signin" type="button" @click="google"><span>G</span>{{isInstitute?'Continue with Google Workspace':'Continue with Google'}}</button><p class="field-help">{{isDemo?'Google sign-in is simulated here; no Google account is accessed.':'Continue to secure Frappe sign-in and choose Google. Your administrator must configure the provider.'}}</p><button class="button primary" :disabled="busy||!accepted">Continue with email code <Icon name="ArrowRight" :size="17"/></button><a v-if="!isDemo" href="/login#forgot" class="text-button">Reset password</a></form>
<form v-else-if="step==='verify'" @submit.prevent="verify"><h3>A little check, just for you.</h3><p>Verify {{email}} to continue.</p><label>Six-digit email code<input v-model="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></label><p v-if="isDemo" class="field-help">Preview code: <strong>123456</strong>. No email was sent. Expires after 10 minutes; five attempts maximum.</p><p v-else class="field-help">Enter the code sent to your email. It expires in ten minutes. Verification submits a request for review and does not grant account privileges.</p><button class="button primary" :disabled="busy">Verify code</button><button type="button" class="button subtle" @click="step='details'">Back</button></form>
<form v-else-if="step==='mobile'" @submit.prevent="verifyMobile"><span class="badge violet">STEP 2 · A LITTLE EXTRA SECURITY</span><h3>Keep your account close.</h3><p>Verify your mobile before creating your profile.</p><label>Mobile number<input v-model="phone" type="tel" required placeholder="+94770000000" maxlength="16"></label><button type="button" class="button subtle" @click="sendMobile">Send mobile code</button><template v-if="mobileSent"><label>Mobile verification code<input v-model="mobileCode" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" required></label><p class="field-help">Preview code: 123456. No SMS is sent. Ten minutes, five attempts.</p><button class="button primary">Verify & build my profile</button></template></form>
<form v-else-if="step==='profile'" @submit.prevent="finishProfile"><span class="badge violet">STEP 3 · MAKE IT YOURS</span><h3>Your name. Your little corner.</h3><label>Unique username<input v-model="username" required pattern="[a-z][a-z0-9_]{2,29}" maxlength="30" placeholder="teenacademysl"></label><p class="field-help">One permanent username per user. Students can find and share @{{username||'yourname'}}.</p><label>About {{isInstitute?'your institute':'you'}}<textarea v-model="bio" maxlength="1000" rows="4" placeholder="Share your story, one thoughtful sentence at a time."></textarea></label><template v-if="kind!=='Student'"><label>Curriculum / education system<input v-model="curriculum" required placeholder="Sri Lankan local syllabus"></label><label>Grades / course levels<input v-model="grades" placeholder="Grades 6–11, undergraduate, professional…"></label><h3>Connect your social profiles</h3><label v-for="(label,key) in {facebook:'Facebook',instagram:'Instagram',twitter:'X / Twitter',youtube:'YouTube'}">{{label}}<input v-model="socials[key]" type="url" placeholder="https://…"></label><p class="field-help">Your profile goes to the Super Admin for review. A verified badge and code are issued after approval.</p></template><button class="button primary">{{kind==='Student'?'Save my profile':'Submit profile for verification'}}</button></form>
<div v-else class="signup-success"><Icon name="CircleCheck" :size="48"/><h3>{{!isDemo?'Email verified. Review pending.':isInstitute?'Verification preview complete.':'You’re ready to explore.'}}</h3><p v-if="profileResult"><strong>@{{profileResult.username}}</strong> · {{profileResult.status}}. {{profileResult.status==='Pending'?'Your verification request is visible to the Platform Owner in Profiles & connections.':'Your profile is ready to discover teachers and institutes.'}}</p><p v-if="isDemo">{{isInstitute?'A real institute stays pending until business review, recovery verification and 2FA setup are completed.':'Your preview is ready. No live account or elevated production permissions have been created.'}}</p><p v-if="!isDemo">Email verified. Your registration is pending review. Institute approval, invitation validation and owner provisioning are completed by the site operator.</p><a v-if="!isDemo" class="button primary" href="/login">Sign in after approval</a><button v-if="isDemo" class="button primary" @click="enter">Explore {{kind}} dashboard</button></div><p v-if="error" role="alert" class="error">{{error}}</p></main></div></section></template>
<style>.signup-shell{background:#faf5ef;color:#53455b;min-height:100vh;padding:30px max(25px,calc((100vw - 1450px)/2))}.signup-shell header{display:flex;justify-content:space-between;align-items:center}.signup-brand{font-size:35px;font-weight:800;color:#625077;text-decoration:none}.signup-brand span{color:#c4a16e}.signup-layout{display:grid;grid-template-columns:1fr 1fr;gap:80px;margin:65px 0}.signup-story{padding:35px 0;position:sticky;top:35px;align-self:start}.signup-story h1{white-space:pre-line;font-size:clamp(34px,4vw,59px);line-height:1.17;letter-spacing:-2px;margin:25px 0}.signup-story p{max-width:470px;font-size:15px;line-height:1.9;color:#88778c}.signup-art{display:flex;align-items:center;justify-content:center;gap:30px;min-height:230px;margin:35px 0;background:radial-gradient(ellipse,#e4dfd0,#ece3f2 65%,transparent 66%);color:#9a82b0}.signup-art span{font-size:80px;color:#caa875}.signup-story small{color:#9a899a}.signup-form{background:#fffcfa;border:1px solid #e9dfeb;border-radius:28px;padding:35px;box-shadow:0 18px 60px #80658d08}.signup-role-tabs{display:flex;gap:6px;flex-wrap:wrap}.signup-role-tabs button{padding:12px 15px;border-radius:12px;background:#f1eaf4;color:#726180;font-size:12px}.signup-role-tabs button[aria-pressed=true]{background:#8f75a8;color:#fff}.owner-entry{display:block;margin:18px 0 30px;font-size:10px}.signup-form h2{font-size:27px;margin-bottom:18px}.signup-form label{display:flex;flex-direction:column;font-size:12px;gap:8px;margin:18px 0}.signup-form :is(input:not([type=checkbox]),select){padding:13px;border:1px solid #e2d7e6;border-radius:11px;width:100%;background:#fffaf6;color:#5c4869}.signup-form .checkbox-label{flex-direction:row;align-items:center;line-height:1.8}.signup-form .field-help,.signup-plan p{font-size:11px;line-height:1.8;color:#88758f}.signup-plan{padding:18px;background:#eee7f3;border-radius:13px;font-size:13px}.signup-success{padding:30px 0;line-height:1.9}.signup-success>svg{color:#75a18d}.signup-form .button{margin:5px 9px 5px 0}@media(max-width:900px){.signup-layout{gap:25px}.signup-story h1{font-size:36px}.signup-form{padding:25px}}@media(max-width:700px){.signup-layout{grid-template-columns:1fr;margin:20px 0}.signup-story{position:static;padding:15px 0}.signup-art,.signup-story>small{display:none}.signup-story h1{font-size:34px}.signup-role-tabs button{flex:1;font-size:10px;padding:11px 8px}}</style>

<style>.signup-shell{background:radial-gradient(at 10% 5%,#e7daf9,transparent 45%),radial-gradient(at 85% 70%,#e9dff7,transparent 50%),#f7f2fc;color:#4e3a67}.signup-story{padding:40px 25px}.signup-story h1{color:#533d72}.signup-art{min-height:270px;border-radius:45px;background:radial-gradient(ellipse,#d2bbea,#ede4fa 66%,transparent 67%);color:#8c65bb;filter:drop-shadow(0 15px 20px #9370b516)}.signup-form{background:#fffaffde;backdrop-filter:blur(15px);border-color:#e2d5f0;box-shadow:0 22px 70px #8f6caf15}.signup-role-tabs button[aria-pressed=true],.signup-form .button.primary{background:#9270c3;color:#fff}.signup-form :is(input:not([type=checkbox]),select,textarea){background:#faf6ff;border:1px solid #e0d3ee;color:#59406e}.signup-form textarea{padding:14px;border-radius:12px;font:inherit}.google-signin{display:flex;align-items:center;justify-content:center;gap:14px;width:100%;padding:14px;margin-top:24px;border:1px solid #d9c9e9;border-radius:14px;background:white;color:#5b476c;font-size:13px}.google-signin span{font-size:21px;font-weight:800;color:#7255ab}.signup-success>svg{color:#9773bc}</style>
